CREATE POLICY ads_media_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='ads-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY ads_media_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='ads-media' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.ads_listings l WHERE l.status='active' AND name=ANY(l.images))));
CREATE POLICY ads_proofs_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='ads-campaign-proofs' AND EXISTS(SELECT 1 FROM public.ads_campaigns c WHERE c.id::text=(storage.foldername(name))[1] AND c.owner_user_id=auth.uid()));
CREATE POLICY ads_proofs_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='ads-campaign-proofs' AND EXISTS(SELECT 1 FROM public.ads_campaigns c WHERE c.id::text=(storage.foldername(name))[1] AND (c.owner_user_id=auth.uid() OR c.advertiser_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
GRANT UPDATE(proof_urls,report) ON public.ads_campaigns TO authenticated;
CREATE FUNCTION public.ads_transition_booking(booking uuid, next_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.ads_bookings; BEGIN SELECT * INTO b FROM public.ads_bookings WHERE id=booking FOR UPDATE; IF b.id IS NULL OR NOT(b.owner_user_id=auth.uid() OR b.advertiser_user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF next_status='disputed' AND b.status NOT IN('completed','cancelled') THEN UPDATE public.ads_bookings SET status=next_status WHERE id=booking; RETURN; END IF; IF b.owner_user_id<>auth.uid() AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Media owner required'; END IF; IF NOT((b.status='booking_confirmed' AND next_status IN('payment_pending','cancelled')) OR (b.status='payment_pending' AND next_status='campaign_active' AND b.payment_status='paid') OR (b.status='campaign_active' AND next_status='completed')) THEN RAISE EXCEPTION 'Invalid transition or payment not confirmed'; END IF; UPDATE public.ads_bookings SET status=next_status WHERE id=booking; END $$;
REVOKE ALL ON FUNCTION public.ads_transition_booking(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ads_transition_booking(uuid,text) TO authenticated;
CREATE TABLE public.ads_disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.ads_bookings(id),opened_by uuid NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved')),decision text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.ads_disputes TO authenticated; GRANT ALL ON public.ads_disputes TO service_role; ALTER TABLE public.ads_disputes ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_disputes_read ON public.ads_disputes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.ads_bookings b WHERE b.id=booking_id AND (b.advertiser_user_id=auth.uid() OR b.owner_user_id=auth.uid())) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_disputes_insert ON public.ads_disputes FOR INSERT TO authenticated WITH CHECK(opened_by=auth.uid() AND status='open' AND decision IS NULL AND EXISTS(SELECT 1 FROM public.ads_bookings b WHERE b.id=booking_id AND (b.advertiser_user_id=auth.uid() OR b.owner_user_id=auth.uid())));
CREATE POLICY ads_disputes_admin_update ON public.ads_disputes FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ads_settings (key text PRIMARY KEY,value jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.ads_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.ads_settings TO authenticated; GRANT ALL ON public.ads_settings TO service_role; ALTER TABLE public.ads_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_settings_public ON public.ads_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY ads_settings_admin ON public.ads_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
